          const duY = u === 1 ? 1 : 0;
          const duZ = u === 2 ? 1 : 0;
          const dwX = w === 0 ? 1 : 0;
          const dwY = w === 1 ? 1 : 0;
          const dwZ = w === 2 ? 1 : 0;
