          const v11 = [width, height, aoBright[2]];
          const v01 = [0, height, aoBright[3]];
          const emit = (A, B, C) => { corner(A[0], A[1], A[2]); corner(B[0], B[1], B[2]); corner(C[0], C[1], C[2]); };
