  if (housingRatio > 1.15 && delta > 0) delta = 0; // 住房不足停止增长

  pop.total = Math.max(0, pop.total + delta);
  // 阶层再分配（简化：新增人口入 worker）
  if (delta > 0) pop.strata.worker += delta;
