    this.tri(x1, y0, z1, x1, y0, z0, x1, y1, z0, col);
    this.tri(x1, y0, z1, x1, y1, z0, x1, y1, z1, col);
    this.tri(x0, y0, z0, x0, y0, z1, x0, y1, z1, col);
