        const cxx = [dx - cx1, 0, dz - cz1];
        const onx = cxy[1] * cxx[2] - cxy[2] * cxx[1];
        const ony = cxy[2] * cxx[0] - cxy[0] * cxx[2];
        const onz = cxy[0] * cxx[1] - cxy[1] * cxx[0];
