      m.box(-1.2, 1.4, 1.2, 0.10, 1.25, 0.10, COL.metal);
      m.box(1.2, 1.4, -1.2, 0.10, 1.25, 0.10, COL.metal);
      m.box(1.2, 1.4, 1.2, 0.10, 1.25, 0.10, COL.metal);
      m.box(0, 2.75, 0, 1.3, 0.10, 1.3, COL.metalDark);
