          if (!Number.isFinite(qty) || qty <= 0) return; // 双保险：输入非法直接忽略
          const res = side === 'buy'
            ? this.app.dispatch('MarketBuy', { systemId, resId: r.resId, qty })
            : this.app.dispatch('MarketSell', { systemId, resId: r.resId, qty });
