function labelWrap(label, control, htmlForId) {
  const wrap = el('label', { class: 'vf-col', ...(htmlForId ? { for: htmlForId } : {}) });
  wrap.appendChild(el('span', { class: 'vf-dim vf-small', text: label }));
  wrap.appendChild(control);
  return wrap;
}

